package com.vasiliyrogozhin85.upospa;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.security.*;
public class PackageLibraryActivity extends Activity{private static final int PICK=9;private TextView out;public void onCreate(Bundle b){super.onCreate(b);UiKit.screen(this);setContentView(ui());}private View ui(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(UiKit.dp(this,16),UiKit.dp(this,16),UiKit.dp(this,16),UiKit.dp(this,24));r.setBackgroundColor(UiKit.BG);TextView h=UiKit.tv(this,"‹  Библиотека пакетов",25,UiKit.TEXT,true);h.setOnClickListener(v->finish());r.addView(h);r.addView(UiKit.tv(this,"Проверка ZIP/IMG/OTA перед установкой",13,UiKit.MUTED,false));out=UiKit.tv(this,"Пакет не выбран",13,UiKit.MUTED,false);r.addView(UiKit.card(this,out),UiKit.top(this,12));r.addView(UiKit.button(this,"Выбрать пакет",UiKit.HOST,v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);}));return r;}protected void onActivityResult(int q,int res,Intent d){super.onActivityResult(q,res,d);if(q==PICK&&res==RESULT_OK&&d!=null&&d.getData()!=null){Uri u=d.getData();out.setText("Выбран: "+u+"\nДля полного анализа откройте экран «Единый отчёт и совместимость».\nSHA-256 и структура пакета будут проверены перед любыми действиями.");}}}
